theorem phaseMomentMatrix_posSemidef {N : ℕ}
    (μ : ProbabilityMeasure PrimePhaseSpace) (d : PacketIndex N → ℂ) :
    (phaseMomentMatrix μ d).PosSemidef

theorem abscissa_lamLog_le {lam : ℕ → ℝ}
    (hsl : ∀ σ : ℝ, 1 < σ → Summable fun n : ℕ => |lam n| / (n : ℝ) ^ σ) :
    LSeries.abscissaOfAbsConv (lamLog lam) ≤ 1

private theorem sum_corr_le {Y : ℝ} (hY : 0 ≤ Y) (M : ℕ) :
    ∑ n ∈ Finset.Icc 2 M, (Real.log n + boxConst) * R (Real.log n - Y) ≤
      (Y + 1 + boxConst) * Real.exp (Y + 1)
